  "technical_and_design_decisions": [
    "Use Go modules to manage external dependencies for externalized components.",
    "Ensure backward compatibility when replacing internal copies with external packages.",
    "Leverage existing CI/CD pipelines for testing and validation.",
    "Prioritize minimal code changes to reduce risk during externalization."
  ],
  "assumptions": [
    "External packages (e.g., gossip, cauthdsl, ccprovider) are compatible with the SDK's current codebase.",
    "All externalized components have stable APIs that do not require significant refactoring.",
    "Existing unit and integration tests cover the affected code paths.",
    "The temporary go.mod workaround (U6) will be removed in a future release."
  ],
